    pub fn new(parties: usize) -> Arc<Self> {
        Arc::new(Self { parties, arrived: AtomicUsize::new(0) })
    }
    pub fn arrive(&self) -> usize {
        self.arrived.fetch_add(1, Ordering::SeqCst) + 1
    }
